-- Lot 216 : payloads 451 a 480 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-249","moteur":"chatgpt","payload":"[RaccourcIA — /headwrapstyle]\n\nMISSION\nTester un nouage de foulard ou turban en préservant l’identité. Respecte tissu, pli et logique du nouage, conserve ligne du visage. Ne présume pas d’appartenance culturelle ou religieuse.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Style de foulard » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Respecte tissu, pli et logique du nouage, conserve ligne du visage. Ne présume pas d’appartenance culturelle ou religieuse. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"09b8efe32976820f8ea22f46feeac30a5d445a8b49f11bf4e54c2ceb1b5f2b4e"},{"ref":"RCI-IMG-249","moteur":"claude","payload":"[RaccourcIA — /headwrapstyle]\n\nMISSION\nTester un nouage de foulard ou turban en préservant l’identité. Respecte tissu, pli et logique du nouage, conserve ligne du visage. Ne présume pas d’appartenance culturelle ou religieuse.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Style de foulard » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Respecte tissu, pli et logique du nouage, conserve ligne du visage. Ne présume pas d’appartenance culturelle ou religieuse. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé,